INSERT INTO game_role_focus VALUES('FC26','cb_wideback','Defend','Wide Back','With a Defend focus, the Wide Back will cover for the fullbacks in all phases but stay close to the defensive line.','["Cover Side", "Stays Back"]','["Defending"]','["Limited Versatility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000000063X36','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','모든 국면에서 풀백을 커버하되 수비 라인에 붙어 있다. 커널: 깊이 4.00 최후방, 양 바깥열 .21씩 대칭 — 어느 쪽 풀백이든 커버하는 형태. 다재다능 제한(−).');
INSERT INTO game_role_focus VALUES('FC26','cb_wideback','Aggressive','Wide Back','With an Aggressive focus, the Wide Back will also close down opponents and intercept passes during the defensive phase.','["Cover Side", "Aggressiveness"]','["Defending"]','["Leaves Gaps"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000003303363X36','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비 국면에서도 상대를 압박·차단한다. 커널: 자기진영 1.00, **터치라인 col0 .39** — CB 중 가장 바깥에 선다(풀백 커버). 뒤 공간(−).');
INSERT INTO game_role_focus VALUES('FC26','cb_wideback','Support','Wide Back','With a Support focus, the Wide Back will move up the side of the pitch to a pass option when their team needs to release pressure.','["Cover Side", "Build-Up Support"]','["Defending"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000300036000663X36','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','압박을 풀어야 할 때 측면으로 올라가 패스 옵션이 된다. 커널: 자기진영 .87·중원 .13, 양 바깥열 .33씩 — 백3의 바깥 CB가 윙백 밑으로 올라오는 그림. 자리 이탈(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_inverted','Build-Up','Inverted Wingback','When asked to Build-Up, the Inverted Wingback will act as a central Playmaker, helping dictate the play.','["Defending", "Stays Back"]','["Pass Option"]','["Attack Support"]',1,'좌우 불일치 — L채택: R={p:[Build-Up Support,Versatile],e:[Out of Position],n:[Defending]}','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000X600360003000030000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 중앙 플레이메이커로 경기를 조율. 커널: 전방 .52·중원 .29·자기진영 .19, col1 .52 — Attack보다 반 행 아래, 하프스페이스 중심. 공격 지원(−). ⚠️ 마첸 적합 .46~.54로 파레토 지배(obs#128) — 겹침을 줄이려면 인버티드가 아니라 wingback.');
INSERT INTO game_role_focus VALUES('FC26','fb_inverted','Attack','Inverted Wingback','When asked to Attack, the Inverted Wingback will act as a central Shadow Striker, helping in the final third.','["Attacking Runs", "Versatile"]','["Stamina Usage"]','["Defending"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','063000X600330003000030000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 중앙 섀도 스트라이커처럼 파이널서드에 관여. 커널: **전방 .68**, col1 .51, **10번 포켓 .68** — 풀백이 CAM 자리로 들어간다. 수비(−). ⚠️ 포켓에서 CAM·인사이드포워드와 충돌 여지(obs#444).');
INSERT INTO game_role_focus VALUES('FC26','dm_boxcrasher','Balanced','Box Crasher','When asked to be Balanced, the Box Crasher will balance their responsibilities between defence and offence.','["Attacking Runs", "Versatile"]','["Out of Position"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','003000060000X0003X3000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공수 책임을 절반씩. 커널: 자기진영 .41·중원 .31·전방 .28 — DM인데 전방 질량이 있다. **하프스페이스 col1 .91** — 자기 쪽 하프스페이스로 박스에 뛰어드는 러너. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','gk_ballplaying','Build-Up','Ball Playing Keeper','A Build-Up focus encourages the Ball-Playing Keeper to push higher up the pitch to support play.','["Pass Option", "Defending"]','["Some Risk"]','["Rush"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000000003X3003X30','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','더 높이 올라가 플레이를 지원한다. 커널: 깊이 3.50 — GK 조합 중 sweeper와 함께 가장 높다. 러시(−). 마르티네스·스즈키 처방(숙련 「볼플레잉 키퍼+」). ⚠️ 커널은 위치만 본다 — 배급 유형(롱/숏)은 PlayStyle 층.');
INSERT INTO game_role_focus VALUES('FC26','dm_widehalf','Build-Up','Wide Half','When set to Build-Up, the Wide Half can move into the Wingback position, and forward into Wide Midfielder territory, when their team is in possession.','["Pass Option", "Wide Support"]','["Supports the Defence"]','["Supports Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000300036363600000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 윙백 자리로, 더 나가면 와이드미드 영역까지 간다. 커널: 자기진영 .80, 양 바깥열 .30씩 — 백3 가변 시 측면으로 벌어지는 하프. 중앙 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','dm_widehalf','Defend','Wide Half','When instructed to Defend, the Wide Half can drop into Fullback and Wingback positions while their team has the ball.','["Defending", "Wide Support"]','["Stays Back"]','["Supports Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000006363630003','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 풀백·윙백 자리로 내려간다. 커널: 자기진영 1.00, 양 바깥열 .30, 깊이 3.20 — Build-Up보다 한 행 아래. 중앙 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','cam_classic10','Versatile','Classic 10','When set to Versatile, the Classic 10 will use their best judgement when determining if they should stay central or use the pitch''s width during attacks.','["Dynamic Width", "Creative"]','["Supports Attacks"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000066X66000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','중앙에 머물지 폭을 쓸지 스스로 판단한다. 커널: 5열 전체에 분산(col0/col4 .18) — Attack보다 넓게 흐른다. 위치를 못 박지 않으므로 ⚠️ 「자리 이탈」이 비용.');
INSERT INTO game_role_focus VALUES('FC26','cam_classic10','Wide','Classic 10','When set to Wide, the Classic 10 is able to drift out to the wing, and dictate attacks from anywhere across the width of the pitch.','["Supports Attacks", "Creative"]','["Wide Support"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000036X63000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','윙까지 흘러나가 폭 전체에서 공격을 지휘한다. 커널: 중앙 .36에 양 바깥열 .11 — Versatile보다 더 넓다. 수비 지원은 희생(−).');
INSERT INTO game_role_focus VALUES('FC26','cam_classic10','Attack','Classic 10','When asked to Attack, the Classic 10 will maintain their position in the pocket behind the forward line, operating as the team''s chief creative force.','["Supports Attacks", "Creative"]','["Limited Versatility"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000006X60000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','전방 라인 바로 뒤 「포켓」에 고정돼 팀의 창조 중심으로 선다. 커널: 전방 2행 100%·중앙 3열 집중(col2 .45), 자기진영 0 — 수비 복귀를 기대하지 말 것(−기동력). 로저스형 10번의 기본형.');
INSERT INTO game_role_focus VALUES('FC26','st_target','Attack','Target Forward','With an Attack focus, the Target Forward is free to focus on going forward, without any defensive instructions.','["Physical", "Attacking"]','["Build-Up Support"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','03X3000000000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비 지시 없이 전진에만 집중. 커널: 깊이 0.00 최전방, 중앙 .62 — 위치만 보면 poacher/Attack과 동일하다(차이는 피지컬 태그·온볼 홀드업). 기동력 부족(−).');
INSERT INTO game_role_focus VALUES('FC26','st_target','Balanced','Target Forward','When Balanced, the Target Forward will drop off from the defensive line, hold up play, and lay the ball off to teammates. They will have minor defensive duties.','["Physical", "Build-Up Support"]','["Defense Support"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00X0000600000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','라인에서 내려와 홀드업 후 레이오프, 약간의 수비 임무. 커널: **중앙열 1.00**(다른 열 0), 깊이 .37 — ST 중 가장 순수한 중앙 기준점. ⚠️ 홀드업 능력 자체는 PlayStyle(Press Proven·Enforcer)·스탯 층이다 — 아브라함에게 「키 크니까 타깃맨」은 오류(duties#161).');
INSERT INTO game_role_focus VALUES('FC26','st_target','Wide','Target Forward','When set to Wide, the Target Forward will drift to the edges of the box in a search for space to make an impact.','["Physical", "Wide Support"]','["Attacking"]','["Support Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','6636600000000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','박스 가장자리로 흘러 공간을 찾는다. 커널: **양 바깥열 .22씩·중앙 .11**, 깊이 0.00 — 최전방인데 좌우로 벌어진다. 중앙 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','st_false9','Attack','False 9','When set to Attack, the False 9 will drop back from the opposition''s defence, and make trailing runs into the box from deep.','["Creative", "Attacking Runs"]','["Movement"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00X0006X60000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비 라인에서 내려온 뒤 깊은 곳에서 박스로 늦게 들어간다. 커널: 깊이 .69 — ST 중 두 번째로 낮다, 중앙 .62. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','st_false9','Build-Up','False 9','With Build-Up, the False 9 will drop back from the opposition''s defence, and operate as a playmaker, leading attacks.','["Creative", "Build-Up Support"]','["Movement"]','["Attacking"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0030006X60000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','내려와서 플레이메이커처럼 공격을 이끈다. 커널: **깊이 .88 = ST 조합 중 가장 낮다**, 하프스페이스 .24씩. 공격(−). 잭슨 아스날전 실측 argmax(.723) — 단 그 하강은 39% 점유 국면 함수였다(obs#444).');
INSERT INTO game_role_focus VALUES('FC26','st_poacher','Support','Poacher','When set to Support, the Poacher will stay close to the opposition defence, aggressively pressing them when in possession, in the hope of triggering a mistake.','["Attacking Runs", "Pressure"]','["Limited Width"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','06X6000300000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','상대 수비에 붙어 보유 시 공격적으로 압박. 커널: 깊이 .12, 하프스페이스 .24씩. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','st_poacher','Versatile','Poacher','With a Versatile focus, the Poacher will use their judgement to determine if they should come back to support their team or apply pressure.','["Attacking Runs", "Versatile"]','["Limited Width"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','06X6000600000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','내려와 돕느냐 압박하느냐를 스스로 판단. 커널: 깊이 .21, 중앙 .57. 자리 이탈(−).');
INSERT INTO game_role_focus VALUES('FC26','st_poacher','Attack','Poacher','With an Attack focus, the Poacher will lurk just off the defensive line, ready to capitalise on any defensive gaps or errors.','["Attacking Runs", "Support Centrally"]','["Limited Width"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','03X3000000000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비 라인 바로 앞에 숨어 실수를 노린다. 커널: **깊이 0.00 = 최전방 행에 전부**, 중앙 .62. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','st_advanced','Support','Advanced Forward','When set to Support, the Advanced Forward will look to make runs from deeper or wider positions, and press the defenders.','["Attacking", "Pressure"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','3636303330000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','더 깊거나 넓은 곳에서 침투하고 수비수를 압박한다. 커널: **하프스페이스 col1/col3 .30씩·중앙 .20** — 중앙이 비는 채널 러너 형태. 왓킨스 처방. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','st_advanced','Attack','Advanced Forward','With an Attack focus, the Advanced Forward will concentrate on goal-scoring opportunities, usually positioning themselves high and central on the pitch.','["Attacking", "Pass Option"]','["Versatile"]','["Limited Width"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','06X6000300000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','득점 기회에 집중, 높고 중앙에. 커널: **깊이 .12**, 중앙 .52 — 최전방 라인. 폭 제한(−).');
INSERT INTO game_role_focus VALUES('FC26','st_advanced','Versatile','Advanced Forward','When set to Versatile, the Advanced Forward has the freedom to move wide when necessary to receive a pass or create space with a run.','["Attacking", "Versatile"]','["Movement"]','["Build-Up Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','36X6300300000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','필요하면 넓게 나가 패스를 받거나 공간을 만든다. 커널: 중앙 .42에 바깥열 .10씩, 깊이 .10. 빌드업 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','w_wideplm','Attack','Wide Playmaker','With an Attack focus, the wide Playmaker will move forward, and receive passes out wide.','["Creative", "Attack Support"]','["Wide Support"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X600063000300000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','앞으로 나가 **바깥에서** 패스를 받는다. 커널: 터치라인 .68·col1 .32, 깊이 .54. ⚠️ 「플레이메이커」지만 폭을 점유한다 — 같은 쪽 풀백 앞을 비우지 않는다. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','w_wideplm','Build-Up','Wide Playmaker','When set to Build-Up, the Wide Playmaker will come short to offer a passing option, while balancing their approach to support the defence if needed.','["Creative", "Build-Up Support"]','["Supports the Defence"]','["Support Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','33000X6000600000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','짧게 내려와 패스 옵션, 필요시 수비 지원. 커널: 터치라인 .68, 깊이 1.00 — Attack보다 반 행 아래. 중앙 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','w_insidefwd','Attack','Inside Forward','When given an Attack focus, the Inside Forward will focus on cutting inside and making attacking runs.','["Attacking", "Support Centrally"]','["Cut Inside"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0X60036300000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','안으로 파고들어 공격 침투. 커널: **하프스페이스 col1 .57·중앙 .32, 터치라인 .11** — 측면을 비우고 안으로. 수비 지원(−). 같은 쪽 풀백이 올라갈 공간을 만드는 조합(docs/20 ⑨).');
INSERT INTO game_role_focus VALUES('FC26','w_insidefwd','Balanced','Inside Forward','When Balanced, the Inside Forward will offer minimal defensive support, and sometimes hold off making runs in behind to instead offer passing options.','["Attack Support", "Pass Option"]','["Cut Inside"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','063006X300330000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','최소 수비 지원, 때로 침투 대신 패스 옵션. 커널: col1 .56, 터치라인 .26, 깊이 .91 — Attack보다 반 행 아래·약간 바깥. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','w_insidefwd','Roaming','Inside Forward','When set to Roaming, the inside Forward is allowed to freely explore and exploit any defensive gaps they can find.','["Movement", "Attack Support"]','["Cut Inside"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','363003X600300000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비 틈을 자유롭게 탐색. 커널: col1 .47·col2 .26, 깊이 .74. 자리 이탈(−).');
INSERT INTO game_role_focus VALUES('FC26','w_winger','Versatile','Winger','The Versatile Winger decides when it''s the right opportunity to attack or defend, and they can swap sides with another Versatile Winger between phases of play.','["Supports Play", "Wide Support"]','["Out of Position"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X6000X0000600003000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공격·수비 시점을 스스로 고르고, 다른 Versatile 윙어와 **사이드를 바꿀 수 있다**. 커널: 터치라인 .83, 깊이 .89. 체력 소모(−). W 슬롯 전용(WM에는 없음).');
INSERT INTO game_role_focus VALUES('FC26','w_winger','Attack','Winger','When set to Attack, the Winger will focus on getting forward, and prefers to make runs behind the defence instead of receiving the ball to feet.','["Wide Support", "Supports Attacks"]','["Pass Option"]','["Defending"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X3000X0000300000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','전진에 집중, 발밑보다 **배후 침투**를 선호. 커널: 터치라인 .88, 깊이 .62, 자기진영 0. 수비(−). ⚠️ 뒤 풀백은 wingback/Balanced(docs/20 ⑨).');
INSERT INTO game_role_focus VALUES('FC26','w_winger','Balanced','Winger','When Balanced, the Winger will offer both defensive and attacking support. They mix making runs behind and offering themselves as a passing option.','["Wide Support", "Pass Option"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','60000X0000600003000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공수 지원을 섞고, 침투와 패스 옵션을 번갈아. 커널: **터치라인 1.00**, 자기진영 .12, 깊이 1.24. 체력 소모(−). ⚠️ 자기진영 .12는 두 줄 4 뱅크를 만들지 못한다(obs#125).');
INSERT INTO game_role_focus VALUES('FC26','cam_halfwinger','Roaming','Half-Winger','When set to Roaming, this attacking Half-Winger will freely alternate the side on which they attack, even during plays.','["Dynamic Side", "Attacking"]','["Wide Support"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X000X66366000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','플레이 중에도 공격하는 사이드를 바꾼다. 커널: M자(col0/col4 .34)이고 깊이 .57 — Attack과 거의 같은 자리, 차이는 좌우 이동 자유. 「자리 이탈」이 비용.');
INSERT INTO game_role_focus VALUES('FC26','cam_halfwinger','Attack','Half-Winger','When set to Attack, the Half Winger can advance freely, sacrificing defensive responsibilities.','["Wide Support", "Attacking"]','["Out of Position"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','6000633333000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','자유롭게 전진하되 수비 책임은 버린다. 커널이 특이하다 — **양 하프스페이스 M자**(col0/col4 .33, 중앙 .11), 깊이 .56으로 CAM 중 가장 높다. 만잠비 실측이 이 M자와 일치(obs#111).');
INSERT INTO game_role_focus VALUES('FC26','cam_halfwinger','Balanced','Half-Winger','When Balanced, the Half Winger will alternate equally between attacking and defending in a measured way.','["Wide Support", "Versatile"]','["Movement"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','3000363336300030000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공격·수비를 절도 있게 번갈아 한다. 커널: M자 유지(col0/col4 .36) + 중원행 .18 — Attack보다 한 행 내려온다. 체력 소모(−). ⚠️ 자기진영은 여전히 0.');
INSERT INTO game_role_focus VALUES('FC26','cam_shadow','Attack','Shadow Striker','When set to Attack, the Shadow Striker will focus on making late runs into the box, filling the space behind the striker.','["Attacking Runs", "Support Centrally"]','["Stamina Usage"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','06X6000X00000000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','스트라이커 뒤 공간으로 늦게 침투해 박스에 들어간다. 커널: 깊이 .31 — **CAM 중 가장 높고 ST 바로 아래**, 중앙 .62. 사실상 두 번째 스트라이커. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','cam_playmaker','Balanced','Playmaker','When asked to be Balanced, the Playmaker will offer defensive support when needed, as well as orchestrating attacks.','["Creative", "Versatile"]','["Pass Option"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0030006X60006000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공격을 지휘하되 필요하면 수비 지원. 커널: 중앙 .61 집중, 중원행 .19, 깊이 1.10 — classic10보다 반 행 아래. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','cam_playmaker','Build-Up','Playmaker','With Build-Up, the Playmaker is asked to drop deeper to get the ball, and orchestrate an attack.','["Creative", "Build-Up Support"]','["Movement"]','["Supports Attacks"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000003X30036300030000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','더 깊이 내려와 볼을 받아 공격을 조립한다. 커널: 전방 .52·중원 .39·**자기진영 .10**, 깊이 1.58 — CAM 조합 중 유일하게 자기진영 질량이 있다. 공격 지원은 희생(−).');
INSERT INTO game_role_focus VALUES('FC26','cam_playmaker','Roaming','Playmaker','When set to Roaming, the Playmaker will have freedom to explore the pitch to find the best spaces to support attacks.','["Creative", "Movement"]','["Out of Position"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0333006X60033300000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','최적 공간을 찾아 피치를 자유롭게 탐색한다. 커널: 중앙 .40에 하프스페이스 .30씩 — 좌우로 퍼진다. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','wm_insidefwd','Balanced','Inside Forward','When Balanced, the Inside Forward will offer minimal defensive support, and sometimes hold off making runs in behind to instead offer passing options.','["Attack Support", "Pass Option"]','["Cut Inside"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','063003X600600000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','최소 수비 지원, 때로 패스 옵션. 커널: col1 .47, 터치라인 .26, 포켓 .74, 깊이 .91. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','wm_insidefwd','Attack','Inside Forward','When given an Attack focus, the Inside Forward will focus on cutting inside and making attacking runs.','["Attacking", "Support Centrally"]','["Cut Inside"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0X60036300300000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','안으로 파고들어 침투. 커널: col1 .52·중앙 .29·**터치라인 .19**, 전방 .90, **10번 포켓 .81**(obs#444 계산) — 측면을 비우는 대신 CAM 칸을 다툰다. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','wm_wideplm','Attack','Wide Playmaker','With an Attack focus, the Wide Playmaker will move forward, and receive passes out wide.','["Creative", "Attack Support"]','["Wide Support"]','["Defence Support"]',1,'좌우 표기차(동의어) — L채택: R={p:[Creative,Supports Attacks],e:[Wide Support],n:[Supports the Defence]}','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000066000330000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','앞으로 나가 바깥에서 패스를 받는다. 커널: **터치라인 .50·하프스페이스 .50**, 전방 .67, 자기진영 0, 포켓 .33 — WM 조합 중 유일하게 반은 안쪽. 수비 지원(−). 맥긴 실측 argmax(.761)이나 뱅크 0.00.');
INSERT INTO game_role_focus VALUES('FC26','wm_wideplm','Build-Up','Wide Playmaker','When set to Build-Up, the Wide Playmaker will come short to offer a passing option, while balancing their approach to support the defence if needed.','["Creative", "Build-Up Support"]','["Supports the Defence"]','["Support Centrally"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000033000660000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','짧게 내려와 패스 옵션. 커널: 터치라인/하프스페이스 .50/.50, 중원 .67·전방 .33, 자기진영 0. 중앙 지원(−). 정본 LM 후보(부엔디아).');
INSERT INTO game_role_focus VALUES('FC26','wm_widemid','Defend','Wide Midfielder','When asked to Defend, the Wide Midfielder will drop into the defensive midfield line and protect the defence.','["Wide Support", "Stays Back"]','["Pass Option"]','["Supports Attacks"]',1,'⚠️ 좌우 불일치(실질) — L채택. R(155)={p:[Creative,Attack Support],e:[Wide Support],n:[Defence Support]}는 설명문(''수비형 미드필드 라인으로 내려와 수비를 보호'')과 정면 모순이라 fut.gg 오류로 판정','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000X3000X300000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비형 미드필더 라인으로 내려와 수비를 보호(「윙백처럼 복귀」). 커널: **자기진영 .50**·중원 .50·전방 0, 터치라인 .77 — 두 줄 4 뱅크를 만드는 조합(obs#39 사다리 최상). 공격 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','wm_widemid','Build-Up','Wide Midfielder','When in Build-Up, the Wide Midfielder will position themselves a little higher up the pitch to support plays, while providing defensive support if needed.','["Build-Up Support", "Wide Support"]','["Supports the Defence"]','["Out of Position"]',1,'좌우 불일치 — L채택: R={p:[Creative,Build-Up Support],e:[Supports the Defence],n:[Support Centrally]}','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000X3000X30000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','조금 높이 서서 플레이 지원, 필요시 수비 지원. 커널: 중원 .50·전방 .50, 터치라인 .77, **자기진영 0**. 자리 이탈(−). 음바예 RM 처방(.878).');
INSERT INTO game_role_focus VALUES('FC26','wm_widemid','Support','Wide Midfielder','When in Support focus, the Wide Midfielder will stay wide to support possession and provide defensive support when needed.','["Wide Support", "Supports Play"]','["Pass Option"]','["Lacks Mobility"]',0,'좌우 완전 일치 — 에메리 프리셋의 뱅크 칸 근거','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000060000X30006000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','「넓게 서서」 점유 지원, 필요시 수비 지원. 커널: 자기진영 .24·중원 .52·전방 .24, 터치라인 .88 — 에메리 뱅크 칸(RM) 기본형. 기동력 부족(−). ⚠️ 폭을 점유하므로 같은 쪽 풀백 전진 공간은 좁다(docs/20 ⑨).');
INSERT INTO game_role_focus VALUES('FC26','wm_winger','Balanced','Winger','When Balanced, the Winger will offer both defensive and attacking support. They mix making runs in behind and offering themselves as a passing option.','["Wide Support", "Pass Option"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','30000X0000X00003000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공수 지원 혼합, 침투와 패스 옵션 교대. 커널: 터치라인 1.00, 자기진영 .12·중원 .38·전방 .50. 체력 소모(−). ⚠️ 자기진영 .12로는 뱅크(0.60)를 못 만든다 — 「Balanced면 복귀한다」는 오독(obs#125).');
INSERT INTO game_role_focus VALUES('FC26','wm_winger','Attack','Winger','When set to Attack, the Winger will focus on getting forward, and prefers to make runs behind the defence instead of receiving the ball to feet.','["Wide Support", "Supports Attacks"]','["Pass Option"]','["Defending"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X0000X0000600000000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','전진 집중, 배후 침투 선호. 커널: **터치라인 1.00**, 전방 .77, 자기진영 0, 깊이 .85. 수비(−). 가르나초 처방(.771). ⚠️ 뒤 풀백은 wingback/Balanced, 전진 풀백은 반대 사이드(C6·docs/20 ⑨).');
INSERT INTO game_role_focus VALUES('FC26','cm_halfwinger','Support','Half-Winger','When set to Support, the Half-Winger will focus on supporting the play instead of simply attacking or defending.','["Wide Support", "Supports Play"]','["Versatile"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000063036633363000300000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공격·수비보다 「플레이 지원」에 집중. 커널: M자(col0/col4 .33) + 전방 .40 — 세 포커스 중 전방 비중이 Balanced보다 높다. 자리 이탈(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_halfwinger','Balanced','Half-Winger','When Balanced, the Half Winger will alternate equally between attacking and defending in a measured way.','["Wide Support", "Versatile"]','["Movement"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000060006633363000300000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공수 균형. 커널: M자 유지, 자기진영 .15·전방 .31 — Attack보다 두 행 폭으로 퍼진다. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_halfwinger','Attack','Half-Winger','When set to Attack, the Half Winger can advance freely, sacrificing defensive responsibilities.','["Wide Support", "Attacking"]','["Out of Position"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','3000360006633360000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','자유 전진, 수비 책임 포기. 커널: **양 바깥열 .38씩 M자**, 전방 .46 — CM 슬롯인데 측면으로 벌어진다. CAM halfwinger보다 한 행 아래(깊이 1.38). 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_playmaker','Roaming','Playmaker','When set to Roaming, the Playmaker will have freedom to explore the pitch to find the best spaces to support attacks.','["Creative", "Movement"]','["Out of Position"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000003666336X630000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','최적 공간을 찾아 자유 이동. 커널: 중앙 .31에 5열 전부 질량(바깥열 .12) — CM 중 가장 넓게 퍼진다. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_playmaker','Attack','Playmaker','When set to Attack, the Playmaker will move forward to support attacks higher up on the field.','["Creative", "Attack Support"]','["Limited Width"]','["Defence Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000363003X300000000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','더 높이 올라가 공격을 지원한다. 커널: 중원 .57·전방 .43·자기진영 0, 중앙 .57 집중, 깊이 1.57. 수비 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_dlp','Build-Up','Deep-Lying Playmaker','When set to Build-Up, the Deep-lying Playmaker will move forward and offer a passing option to support attacks.','["Creative", "Versatile"]','["Pass Option"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000030006X600060000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','앞으로 나와 패스 옵션을 준다. 커널: 중원 .71·전방 .10·자기진영 .19, 깊이 2.10. 수비 지원은 희생(−). ⚠️ DM 슬롯의 dm_dlp/Build-Up(자기진영 .45)보다 훨씬 높다 — 슬롯 타입이 다르면 같은 이름이라도 위치가 다르다.');
INSERT INTO game_role_focus VALUES('FC26','cm_dlp','Defend','Deep-Lying Playmaker','With a Defend focus, the Deep-lying Playmaker will focus on closing down passing lanes and staying back while their team attacks.','["Defending", "Creative"]','["Intercepts Passes"]','["Attacking"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000000003X300030000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','패스 길을 막고 팀 공격 시 뒤에 남는다. 커널: 중원 .84·전방 0, 깊이 2.16. 공격(−). CM 슬롯에서 「내려앉는」 조합.');
INSERT INTO game_role_focus VALUES('FC26','cm_holding','Ball-Winning','Holding','The Ball-Winning focus tasks the Holding Midfielder with aggressively intercepting passing as part of their defensive focus.','["Defending", "Aggressiveness"]','["Limited Versatility"]','["Pass Option"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000000006X600060000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공격적으로 패스를 차단한다. 커널: 중원 .79·자기진영 .21·전방 0, 하프스페이스 .21씩 — 중원 벨트 사냥꾼. 패스 옵션(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_holding','Defend','Holding','When instructed to Defend, the Holding Midfielder will move slightly higher to offer a passing option, but will otherwise focus on defending.','["Defending", "Stays Back"]','["Pass Option"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000000006X600363000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','약간 올라가 패스 옵션을 주되 수비 집중. 커널: 자기진영 .35·중원 .65 — ⚠️ Ball-Winning보다 **더 깊다**(자기진영 .35 vs .21). 기동력 부족(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_b2b','Ball-Winning','Box-To-Box','When asked to be Ball-Winning, the Box-to-Box Midfielder will focus on recovering the ball while providing central support in attack and defence.','["Aggressiveness", "Supports Play"]','["Support Centrally"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0030003X3003X3003X3000300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','볼 회수에 집중하면서 공수 중앙 지원. 커널: 3분할 .35/.30/.35, 하프스페이스로 .17씩 퍼진다 — Balanced보다 좌우로 넓게 사냥. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','cm_b2b','Balanced','Box-To-Box','When asked to be Balanced, the Box-to-box Midfielder will cover the centre of the pitch in attack and defence.','["Attack Support", "Defence Support"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0030000X0003X3000X0000300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공수 양면에서 중앙을 커버한다. 커널: 자기진영 .31·중원 .38·전방 .31 **균등 3분할**, 중앙열 .86 — 진짜 박스투박스. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','dm_dlp','Build-Up','Deep-Lying Playmaker','When set to Build-Up, the Deep-lying Playmaker will move forward and offer a passing option to support attacks.','["Creative", "Versatile"]','["Pass Option"]','["Supports the Defence"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000030003X3003X3000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','앞으로 나와 패스 옵션. 커널: 자기진영 .45·중원 .45·전방 .10, col1 .79 — 자기 쪽 하프스페이스 기준점. 수비 지원(−). 바클리·고메스의 기본 축.');
INSERT INTO game_role_focus VALUES('FC26','dm_dlp','Roaming','Deep-Lying Playmaker','The Roaming focus allows the Deep-lying Playmaker to move across the width of the pitch to support attacks.','["Creative", "Movement"]','["Pass Option"]','["Out of Position"]',0,'에메리 프리셋 LDM 만잠비 처방의 1차 근거','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000003330066600363000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','폭 전체를 가로질러 공격을 지원한다. 커널: col1 .45·col2 .36·col3 .18 — 반대 하프스페이스까지 넘어간다, 전방 .18. 자리 이탈(−). 카마라·바클리 처방.');
INSERT INTO game_role_focus VALUES('FC26','dm_dlp','Defend','Deep-Lying Playmaker','With a Defend focus, the Deep-lying Playmaker will focus on closing down passing lanes and staying back while their team attacks.','["Defending", "Creative"]','["Intercepts Passes"]','["Attacking"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000333003X3000000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','패스 길 차단, 공격 시 잔류. 커널: 자기진영 .68·중원 .32·전방 0, 깊이 2.68. 공격(−).');
INSERT INTO game_role_focus VALUES('FC26','dm_centrehalf','Defend','Centre-Half','When set to Defend, the Centre Half will focus on their defensive duties.','["Defending", "Support Centrally"]','["Limited Versatility"]','["Wide Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000000003X3003X30','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비 임무만. 커널: 자기진영 1.00, 깊이 3.50 — DM 슬롯에서 **CB 라인까지 내려앉는다**(백3화). 폭 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','dm_holding','Ball-Winning','Holding','The Ball-Winning focus tasks the Holding Midfielder with aggressively intercepting passing as part of their defensive focus.','["Defending", "Aggressiveness"]','["Limited Versatility"]','["Pass Option"]',0,'에메리 프리셋 RDM 카마라 처방의 1차 근거 — negative가 Pass Option인 것이 obs#32의 ''창조 전무'' 실측과 정합','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000000006X6000300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','공격적 패스 차단. 커널: 자기진영 1.00, 깊이 3.14 — DM 중 가장 깊은 사냥. 패스 옵션(−).');
INSERT INTO game_role_focus VALUES('FC26','dm_holding','Roaming','Holding','When set to Roaming, the Holding Midfielder will move across the width of the pitch to close passing lanes, and step up to press attackers.','["Defending", "Movement"]','["Pass Option"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000033306XXX600000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','폭을 가로질러 패스 길을 막고 올라가 압박한다. 커널: 자기진영 .82, **5열 전부에 질량**(col0 .20 ~ col4 .12) — 홀딩 중 유일하게 좌우로 넓다. 체력 소모(−). 오나나 처방.');
INSERT INTO game_role_focus VALUES('FC26','dm_holding','Defend','Holding','When instructed to Defend, the Holding Midfielder will move slightly higher to offer a passing option, but will otherwise focus on defending.','["Defending", "Stays Back"]','["Pass Option"]','["Lacks Mobility"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000030003X3000300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','약간 올라가 패스 옵션, 나머지는 수비. 커널: 자기진영 .88·중원 .12, 깊이 3.00. 기동력 부족(−).');
INSERT INTO game_role_focus VALUES('FC26','cb_bpd','Aggressive','Ball-Playing Defender','When asked to be Aggressive, the Ball-Playing Defender will focus on intercepting passes and closing down opponents.','["Pressure", "Aggressiveness"]','["Build-Up Support"]','["Leaves Gaps"]',0,'에메리 프리셋 RCB 콘사 처방의 1차 근거 — obs#17 ''스텝아웃'' 실측과 정합','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000363006X6003630','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','패스 차단과 전진 압박에 집중한다. 커널: 자기진영 .78·중원 .22, 깊이 3.07 — CB 조합 중 가장 높이 선다. 뒤에 공간을 남긴다(−Leaves Gaps).');
INSERT INTO game_role_focus VALUES('FC26','cb_bpd','Build-Up','Ball-Playing Defender','The Build-Up focus moves the Ball-playing Defender into more of a holding defensive midfielder during possession.','["Build-Up Support", "Defence Support"]','["Versatile"]','["Out of Position"]',0,'에메리 프리셋 LCB 파우 토레스 처방의 1차 근거','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000030006X6006X60','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 홀딩 DM 위치로 올라간다. 커널: 자기진영 .93, 깊이 3.39 — ⚠️ 이름은 Build-Up이지만 Aggressive보다 **낮게** 선다(전진은 볼 있을 때만). 자리 이탈(−).');
INSERT INTO game_role_focus VALUES('FC26','cb_bpd','Defend','Ball-Playing Defender','When set to Defend, the Ball-playing Defender will step up a little to support teammates during possession.','["Defending", "Build-Up Support"]','["Stays Back"]','["Leave Gaps"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000363006X60','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 조금만 올라가 동료를 지원한다. 커널: 자기진영 1.00, 깊이 3.61. 뒤 공간(−). 콘사·파우 토레스 계열의 기본형.');
INSERT INTO game_role_focus VALUES('FC26','cb_stopper','Aggressive','Stopper','When asked to be Aggressive, the Stopper will push up into the base of midfield to intercept passes and close down attackers.','["Pressure", "Aggressiveness"]','["Defence Support"]','["Leaves Gaps"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000030006X6000X00','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','미드필드 밑까지 올라가 패스를 끊고 공격수를 압박한다. 커널: 자기진영 .81, **하프스페이스 col1 .72**(터치라인 0) — 안쪽으로 튀어나가는 형. 뒤 공간(−).');
INSERT INTO game_role_focus VALUES('FC26','cb_stopper','Balanced','Stopper','With a Balanced focus, the Stopper will intercept passes and pressure attackers receiving the ball.','["Defending", "Pressure"]','["Aggressiveness"]','["Leave Gaps"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000666003X30','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','패스를 끊고 볼 받는 공격수를 압박한다. 커널: 자기진영 1.00, 깊이 3.57 — Aggressive보다 반 행 아래, 형태는 같다.');
INSERT INTO game_role_focus VALUES('FC26','cb_defender','Balanced','Defender','With a Balanced focus, the Defender will step up to close down attackers when needed.','["Defending", "Stays Back"]','["Limited Versatility"]','["Limited Width"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000333006X60','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','필요할 때만 올라가 상대를 막는다. 커널: 자기진영 1.00, 깊이 3.76 — bpd/Defend보다 더 깊다. 폭 제한(−).');
INSERT INTO game_role_focus VALUES('FC26','cb_defender','Defend','Defender','When asked to Defend, the Defender will focus only on their defensive responsibilities.','["Stays Back", "Defending"]','["Limited Versatility"]','["Pass Option"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000000006X60','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','수비 책임만 본다. 커널: 자기진영 1.00, **깊이 4.00 = 최후방 고정**. 패스 옵션이 되지 않는다(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_att_wb','Attack','Attacking Wingback','When asked to Attack, the Attacking Wingback will push even higher up the pitch, and perform fewer defensive duties.','["Attacking", "Wide Support"]','["Out of Position"]','["Defending"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','X000060000300003000030000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','「더 높이 올라가고 수비 임무를 덜 한다」. 커널: **전방 .64**·자기진영 .24, 터치라인 1.00, 깊이 1.32 — 풀백 조합 중 가장 높다. ⚠️ 앞 공간이 비어야 발동한다(EA 「open space in front」, docs/20 ⑨) — 같은 쪽에 터치라인형 와이드가 있으면 올라가지 못한다. 수비(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_att_wb','Support','Attacking Wingback','When asked to Support, the Attacking Wingback will rarely sprint back to defend, unless their team has been hit on the counter.','["Wide Support", "Attacking"]','["Stamina Usage"]','["Defending"]',0,'⚠️ 에메리 프리셋 LB 에스투피냔·RB 보가르드 처방. negative가 Defending인 것이 C2(풀백 한 명씩 전진) 붕괴의 1차 근거 — 양쪽 풀백을 이 포커스로 두면 두 측면 모두 수비 복귀가 negative가 된다','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','30000X0000600006000030000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','「역습 당할 때 빼고는 좀처럼 수비 복귀 스프린트를 하지 않는다」. 커널: 전방 .46·자기진영 .32, 깊이 1.86. ⚠️⚠️ **전진을 늘리는 포커스가 아니라 복귀를 줄이는 포커스다** — 「풀백을 더 올리려고」 Support를 주는 것은 정의상 빗나간다, 그건 Attack. 시즌 기본은 Support, 홈·지배 경기 변형에서 Attack(마첸 duties 운용). 수비(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_wingback','Support','Wingback','When asked to Support, the Wingback can only attack when their team has controlled possession, and only defend when the team doesn''t have the ball.','["Wide Support", "Defence Option"]','["Out of Position"]','["Stamina Usage"]',0,'C2 비대칭 복원 옵션 — plus에 Defence Option이 있어 att_wb/Support(neg: Defending)와 정확히 대비된다','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000030000X60006000060000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','「팀이 점유를 통제할 때만 공격, 비보유 시만 수비」. 커널: 자기진영 .39·중원 .52, col0 .81·col1 .19 — Balanced보다 중원에 머물고 약간 안쪽. 수비 옵션(+). 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_wingback','Balanced','Wingback','With Balanced, the Wingback is given license to stay forward even when the team is out of possession, or drop back into defence when needed.','["Wide Support", "Movement"]','["Versatile"]','["Stamina Usage"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000030000X0000X000060000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','「비보유 시에도 앞에 남을 자격, 필요하면 수비 복귀」. 커널: 자기진영 .55·중원 .34·전방 .10, **터치라인 1.00이지만 row0(최전방)은 비어 있다** — 이 기하 덕에 높이 선 윙어와 수직 분리된다(겹침 .553, obs#128). 윙어 뒤 풀백의 기본형. 체력 소모(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_falseback','Balanced','Falseback','When set to Balanced, the Falseback positions themselves as a Central Midfielder when their team is in possession.','["Build-Up Support", "Defence Support"]','["Limited Width"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000003X3003630060000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 중앙 미드필더 자리로 들어온다. 커널: 자기진영 .53·중원 .47, **하프스페이스 col1 .47**(터치라인 .35) — 폴스백은 안쪽으로 접힌다. 자리 이탈(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_falseback','Defend','Falseback','When set to Defend, the Falseback operates as a Defensive Midfielder when the team has the ball.','["Defending", "Build-Up Support"]','["Limited Width"]','["Out of Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000033003X600X3000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 수비형 미드필더로 움직인다. 커널: 자기진영 .84·중원 .16, col1 .42 — Balanced보다 한 행 아래에서 안쪽으로. 자리 이탈(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_fullback','Versatile','Fullback','When set to Versatile, the Fullback can move inside to form a back three or push slightly forward and wider to support build-up.','["Versatile", "Defending"]','["Pass Option"]','["Supports Attack"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000000030000X3000XX300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','백3로 접히거나 약간 앞·바깥으로 나가는 것을 스스로 고른다. 커널: 자기진영 .92, col0 .59·col1 .33 — Balanced와 Defend의 중간. 공격 지원(−).');
INSERT INTO game_role_focus VALUES('FC26','fb_fullback','Balanced','Fullback','When set to Balanced, the Fullback is granted more freedom to push slightly forward and wider in support of attacks.','["Defending", "Stays Back"]','["Pass Option"]','["Attack Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','000000000030000X3000X6000','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','「약간 앞·바깥으로 나가 공격 지원」. 커널: 자기진영 .91, 터치라인 .72·col1 .28, 깊이 3.41. 공격 지원(−). ⚠️ 이름이 Balanced지만 자기진영 .91 — 사실상 수비형.');
INSERT INTO game_role_focus VALUES('FC26','fb_fullback','Defend','Fullback','When set to Defend, the Fullback will move inside to form a back three when their team is in possession.','["Stays Back", "Defending"]','["Limited Versatility"]','["Wide Support"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000000033000XX300','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','보유 시 **안으로 들어와 백3를 만든다**. 커널: 자기진영 1.00, col0 .45·col1 .45 — 절반이 하프스페이스로. 폭 지원(−). 에메리가 원한다는 「하이브리드 백3 좌측 수비수」(마첸 duties#6)가 이 조합에 가장 가깝다.');
INSERT INTO game_role_focus VALUES('FC26','gk_sweeper','Build-Up','Sweeper Keeper','A Build-Up focus encourages the Sweeper Keeper to push even higher up the pitch to collect the ball and support play.','["Rush", "Pass Option"]','["Some Risk"]','["Stay in Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','00000000000000003X300XXX0','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','「더욱 높이」 올라가 볼을 잡고 플레이를 지원. 커널: 깊이 3.65(sweeper/Balanced와 동일), col1/col3 .28. ⚠️ 스즈키 실측은 골라인 고정형이라 이 계열이 기각됐다(duties#121).');
INSERT INTO game_role_focus VALUES('FC26','gk_sweeper','Balanced','Sweeper Keeper','A Balanced focus allows the Sweeper Keeper to leave their area to collect balls close to their box.','["Rush", "Defending"]','["Some Risk"]','["Stay in Position"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000363006X60','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','박스 근처의 볼을 잡으러 박스를 떠난다. 커널: 깊이 3.65, 하프스페이스 .26씩 — Balanced 골키퍼보다 넓고 높다. 자리 고수(−).');
INSERT INTO game_role_focus VALUES('FC26','gk_goalkeeper','Balanced','Goalkeeper','With a Balanced focus, the Goalkeeper will occasionally leave their area to collect long or loose balls.','["Stay in Position", "Defending"]','["Some Risk"]','["Rush"]',0,NULL,'fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000030003X30','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','가끔 박스를 떠나 롱볼·루즈볼을 잡는다. 커널: 깊이 3.84, 중앙 .68. 러시(−).');
INSERT INTO game_role_focus VALUES('FC26','gk_goalkeeper','Defend','Goalkeeper','With a Defend focus, the Goalkeeper won''t rush out to collect long or loose balls.','["Stay in Position", "Defending"]','["Low Risk"]','["Rush"]',0,'에메리 프리셋 GK 마르티네스 처방 — Low Risk가 equal인 유일한 항목','fut.gg /api/fut/roles/ (2026-07-31 브라우저 스크랩)','0000000000000000000003X30','fut.gg /api/fut/roles/ 히트맵 (수집 2026-07-31, obs#90 커널 27/27 검증 · obs#93 변형 규명) — 툴 fc26-heatmap.html MAPS에서 이관, 키가 game_role_focus 85행과 양방향 차집합 0으로 일치 확인','롱볼·루즈볼에 뛰어나오지 않는다. 커널: **깊이 4.00 = 골라인 고정**. ⚠️ GK 조합은 커널이 전부 .96~.98대로 수렴해 적합값으로 우열을 가릴 수 없다(obs#220) — 평균 위치·duties로 판정.');
